<script setup lang="ts">import { computed, onMounted, ref } from "vue"; import { listItems, type Item } from "../api"; const items = ref<Item[]>([]); const query = ref(""); const error = ref(""); const filtered = computed(() => items.value.filter((item) => `${item.sku} ${item.name}`.toLowerCase().includes(query.value.toLowerCase()))); onMounted(async () => { try { items.value = await listItems(); } catch (reason) { error.value = (reason as Error).message; } });</script><template><section><header><div><p class="eyebrow">Operaciones</p><h1>Almacen <span class="count">{{ filtered.length }}</span></h1></div><RouterLink class="button-link" :to="{ name: 'inventory.create' }">Nuevo material</RouterLink></header><div class="filter-bar"><input v-model="query" placeholder="Buscar por SKU o nombre" /><RouterLink :to="{ name: 'inventory.alerts' }">Ver alertas</RouterLink><RouterLink :to="{ name: 'suppliers.list' }">Proveedores</RouterLink><RouterLink :to="{ name: 'purchase-orders.list' }">Ordenes de compra</RouterLink></div><p v-if="error" class="feedback error">{{ error }}</p><div class="customer-list"><p v-if="!filtered.length" class="empty">No hay materiales registrados.</p><RouterLink v-else v-for="item in filtered" :key="item.id" class="customer-row" :to="{ name: 'inventory.detail.general', params: { id: item.id } }"><strong>{{ item.name }}</strong><span>{{ item.sku }}</span><span>{{ item.stock }} {{ item.unit }}</span><span class="status-pill">Min. {{ item.minimumStock }}</span></RouterLink></div></section></template>